    InspectionChecklist: [ { id: "opf_soot", category: "Engine", question: "Is the OPF soot load within safe limits?", howToCheck: "Diagnostic scan of group IDE06059 to check saturation level. If high, force regen.", costUSD: 150, costEUR: 130, severity: "HIGH" }, { id: "coolant_module", category: "Cooling", question: "Any crusty pink leaks near the module?", howToCheck: "Visual check under the intake manifold on the transmission side of the block.", costUSD: 600, costEUR: 550, severity: "HIGH" }, { id: "turbo_rod", category: "Engine", question: "Is the actuator arm stuck?", howToCheck: "Manual sweep when cold. It should move freely without binding.", costUSD: 400, costEUR: 350, severity: "MEDIUM" }, { id: "mount_vibration", category: "Engine", question: "Shaking felt in steering wheel?", howToCheck: "Cold start idle feel. 3-cylinder engines are sensitive to mount wear.", costUSD: 300, costEUR: 250, severity: "MEDIUM" }, { id: "clutch_uphill", category: "Transmission", question: "Slipping in high gear?", howToCheck: "Uphill pull in 4th gear at low RPM to check for clutch hold.", costUSD: 700, costEUR: 600, severity: "HIGH" }, { id: "exhaust_sensors", category: "Electronics", question: "Any lambda or temp sensor codes?", howToCheck: "OBD scan for exhaust gas temperature sensor plausibility signals.", costUSD: 100, costEUR: 80, severity: "LOW" }, { id: "oil_cap_residue", category: "Engine", question: "Yellow sludge under cap?", howToCheck: "Visual check. Common on short-trip cars, indicates condensation buildup.", costUSD: 50, costEUR: 40, severity: "MEDIUM" }, { id: "serpentine_belt", category: "Engine", question: "Are there cracks on the belt?", howToCheck: "Visual inspection of the ribbed side of the accessory belt.", costUSD: 100, costEUR: 80, severity: "LOW" }, { id: "dsg_clunk", category: "Transmission", question: "Metal clunking in traffic?", howToCheck: "Low speed 1st to 2nd shifts listening for engagement noise.", costUSD: 1500, costEUR: 1300, severity: "CRITICAL" }, { id: "suspension_boots", category: "Suspension", question: "Are CV boots torn?", howToCheck: "Wheel arch inspection turning the wheel fully to both sides.", costUSD: 200, costEUR: 150, severity: "MEDIUM" } ],
